			function onBtn4Click(/* cpr.events.CMouseEvent */ e){
			    /** 
			     * @type cpr.controls.Button
			     */
			    var btn4 = e.control;
			    
			    if (!confirm("삭제하시겠습니까?")) {
			        return;
			    }
			    
			    ///** @type cpr.data.DataSet */ 
			    //var ds = app.getAppProperty("ds");
			    var ds = app.lookup("dsMenuList");
			    
			    ///** @type cpr.controls.Grid */ 
			    //var grd = app.getAppProperty("grd");
			    var grd = app.lookup("grdList");
			    
			    var rowCount = ds.getRowCount();
			    
			    //console.log("rowCount", rowCount);
			    
			    var rowIndex = grd.getSelectedRowIndex();
			    
			    var dsDeletedMenuId = app.lookup("dsDeletedMenuId");
			    
			    //console.log("rowIndex", rowIndex);
			    
			    if (rowIndex == -1) {
			        return;
			    }

			    var prevRow = null;
			    if (rowIndex - 1 >= 0) {
			        prevRow = ds.getRow(rowIndex - 1);
			    }
			    
			    var nextRow = null;
			    if (rowIndex + 1 < rowCount) {
			        nextRow = ds.getRow(rowIndex + 1);
			    }

			    if (hasChildren(ds, rowIndex, rowCount)) {
			        
			        var row = ds.getRow(rowIndex);
			        var currLevel = row.getValue("MENU_LEVELA_NO");
			        
			        var nextIdx = nextRowIndexSameLevel(ds, rowIndex, "small");

			        //console.log("delete nextIdx", nextIdx);
			        
			        if (nextIdx == ds.getRowCount()) {
			            
			            var findRows = ds.findAllRow("MENU_LEVELA_NO <= " + row.getValue("MENU_LEVELA_NO"));
			            
			            if (findRows[findRows.length - 1].getIndex() == rowIndex) {
			                nextIdx = ds.getRowCount();
			            } else {
			                return;
			            }
			        }
			        
			        for (var i = nextIdx - 1; i >= rowIndex; i--) {
			            //console.log("deleteIdx", i);
			            dsDeletedMenuId.addRowData({"MENU_NO" : ds.getRow(i).getValue("MENU_NO")});
			            ds.deleteRow(i);
			        }

			        ds.commit();
			                
			    } else {
			        dsDeletedMenuId.addRowData({"MENU_NO" : ds.getRow(rowIndex).getValue("MENU_NO")});
			        ds.deleteRow(rowIndex);
			        ds.commit();
			    }
			    
			}



			function hasChildren(ds, rowIndex, rowCount) {

			    var currRow = ds.getRow(rowIndex);
			    var currLevel = currRow.getValue("MENU_LEVELA_NO");
			    
			    // 다음 row 가 존재하면서
			    if (rowIndex + 1 < rowCount) {
			        
			        // 다음 row level 이 더 클 때
			        var nextRow = ds.getRow(rowIndex + 1);
			        var nextLevel = nextRow.getValue("MENU_LEVELA_NO");
			        
			        if (currLevel < nextLevel) {
			            return true;
			        }
			    }
			    
			    return false;
			}

			function hasParent() {}

			function prevRowIndexSameLevel(ds, rowIndex) {

			    var currRow = ds.getRow(rowIndex);
			    var currLevel = currRow.getValue("MENU_LEVELA_NO");
			    
			    var findRows = ds.findAllRow("MENU_LEVELA_NO <= " + currRow.getValue("MENU_LEVELA_NO"));

			    //console.log("findRows2", findRows);
			    
			    var prevIdx = rowIndex;
			    
			    for (var i=0; i < findRows.length; i++) {
			        if (rowIndex > findRows[i].getIndex()) {
			            prevIdx = findRows[i].getIndex();
			        } else {
			            //if (rowIndex == prevIdx) {
			                //return -1;
			            //} else {
			                if (i == 0) {
			                    return -1;
			                } else if (findRows[i - 1].getValue("MENU_LEVELA_NO") < currRow.getValue("MENU_LEVELA_NO")) {
			                    return -1;
			                } else {
			                    return prevIdx;
			                }
			            //}
			        }
			    }

			    return -1;
			}

			function nextRowIndexSameLevel(ds, rowIndex, small) {

			    var currRow = ds.getRow(rowIndex);
			    var currLevel = currRow.getValue("MENU_LEVELA_NO");
			    
			    var findRows = ds.findAllRow("MENU_LEVELA_NO <= " + currRow.getValue("MENU_LEVELA_NO"));

			    //console.log("findRows1", findRows);
			    
			    if (findRows[findRows.length - 1].getIndex() == rowIndex) {
			        return ds.getRowCount();
			    }

			    var nextIdx = rowIndex;
			        
			    for (var i = findRows.length - 1; i >= 0; i--) {
			        if (rowIndex < findRows[i].getIndex()) {
			            nextIdx = findRows[i].getIndex();
			        } else {
			            if (rowIndex == nextIdx) {
			                return ds.getRowCount();
			            } else {
			                if (small != "small" && findRows[i + 1].getValue("MENU_LEVELA_NO") < currRow.getValue("MENU_LEVELA_NO")) {
			                    return ds.getRowCount();
			                } else {
			                    return nextIdx;
			                }
			            }
			        }
			    }
			    
			    return ds.getRowCount();
			}


