			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(/* cpr.events.CMouseEvent */ e){
			    /** 
			     * @type cpr.controls.Button
			     */
			    var btnSave = e.control;
			    
			    /** @type cpr.data.DataSet */
			    var ds = app.lookup("dsMenuList");
			    var grd = app.lookup("grdList");
			    var cmb = app.lookup("cmb2");
			    
			    //var targetDS = app.lookup("dsMenuList");
			    
			    //targetDS.clear();

			    //ds.commit();
			    ds.clearFilter();
			    
			    var checkCnt = ds.getConditionalRowCount("MENU_NM == null or MENU_NM == ''");
			    if (checkCnt > 0) {
			        util.Msg.alert(app, "메뉴명을 확인해주시기 바랍니다.");
			        return;
			    }
			    
			    cmb.value = 0;
			    
			    //ds.copyToDataSet(targetDS);
			    //ds.clearFilter();
			    /** @type cpr.data.DataSet */
			    var dsMenuListStr = app.lookup("dsMenuListStr");
			    
			    dsMenuListStr.clear();
			    
			    for (var i=0; i < ds.getRowCount(); i++) {
			        var row = ds.getRowData(i);
			        
			        var rowDataStr = row["MENU_NO"] + "|" + 
			                            row["MENU_NM"] + "|" + 
			                            row["URL_ADDR"] + "|" + 
			                            row["PROGRM_NM"] + "|" + 
			                            row["UP_MENU_ID"] + "|" + 
			                            row["UP_MENU_NM"] + "|" + 
			                            row["MENU_LEVELA_NO"] + "|" + 
			                            row["MENU_RM_CN"] + "|" + 
			                            row["PROGRM_ID"] + "|" + 
			                            row["PARA_CN"] + "|" + 
			                            row["TOP_MENU_ID"] + "|" + 
			                            row["TOP_MENU_NM"] + "|" + 
			                            row["TWO_DEPTH_MENU_ID"] + "|" + 
			                            row["TWO_DEPTH_MENU_NM"] + "|" +
			                            ds.getRowStateString(i);

			        dsMenuListStr.addRowData({ "str" : rowDataStr });
			        dsMenuListStr.commit();
			    }
			    
			    
			    //console.log("dsMenuList", ds.getRowCount());
			    
			    /** @type cpr.data.DataSet */
			    var dsDeletedMenuId = app.lookup("dsDeletedMenuId");
			    
			    //console.log("dsDeletedMenuId", dsDeletedMenuId.getRowCount());
			    
			    util.Submit.send(app, "subSaveMenu", function(pbSuccess) {
			        if (pbSuccess) {
			            util.Submit.send(app, "subMenu", function(){
			                
			                //ds.clear();
			                
			                //targetDS.copyToDataSet(ds);
			                
			                ds.commit();
			                
			                util.Msg.alert(app, "저장되었습니다.", null, function(){
								 cmb.value = 0;
							 });
			                
			            });
			        }
			    });
			    
			}



